"""V*+ (w>=0) for the integer lattice with one generator moved: is the integer position a local maximum?
usage: localmax_032.py T N"""
import sys, numpy as np
from math import log, exp
from lattice_032A import setup, vstar, lmin
T=float(sys.argv[1]); N=int(sys.argv[2])
def beurling(g2, g3=3.0):
    # monoid generated by g2, g3 and the primes >= 5, elements < e^{2T}
    X=exp(2*T); primes=[p for p in range(5,int(X)+2) if all(p%q for q in range(2,int(p**.5)+1))]
    gens=[g2,g3]+primes; els={1.0}
    for g in gens:
        new=set()
        for e in els:
            v=e*g
            while v<X: new.add(v); v*=g
        els|=new
    return np.array(sorted(log(e) for e in els if e>1.0001))
for name,g2,g3 in [("int",2,3),("2->1.98",1.98,3),("2->2.02",2.02,3),("2->1.995",1.995,3),("2->2.005",2.005,3),("3->2.97",2,2.97),("3->3.03",2,3.03)]:
    xs=beurling(g2,g3); M0,C=setup(T,N,xs)
    V,w,mult=vstar(M0,C,True)
    print(f"T={T} N={N} {name:9s} npts={len(xs)} V+={V:+.5f}",flush=True)
